naming-conventions.example:
# module: user_repository.py MAX_PAGE_SIZE = 100 # CONSTANT_NAME
class UserRepository: # ClassName def __init__(self) -> None: self._cache: dict[str, User] = {} # _protected_name
def get_by_id(self, user_id: str) -> User | None: # method_name return self._cache.get(user_id)
def _invalidate_cache(self) -> None: # _protected_name self._cache.clear()
class UserNotFoundError(Exception): # suffix Error pass

type-hints.example:
from __future__ import annotations

from collections.abc import Callable, Sequence
from typing import Any, TypeVar

T = TypeVar("T")

def first_or_default(items: Sequence[T], default: T) -> T:
    return items[0] if items else default

def retry(
    func: Callable[..., T],
    *,
    max_attempts: int = 3,
    exceptions: tuple[type[Exception], ...] = (Exception,),
) -> T:
    for attempt in range(max_attempts):
        try:
            return func()
        except exceptions:
            if attempt == max_attempts - 1:
                raise
    raise RuntimeError("unreachable")

# Modern union syntax
def find_user(user_id: str) -> User | None:
    ...

# Self in classmethods
from typing import Self

class Config:
    @classmethod
    def from_env(cls) -> Self:
        return cls(...)

logging.example:
import logging

logger = logging.getLogger(__name__)   # module-level logger

def process_order(order_id: str) -> None:
    logger.info("Processing order %s", order_id)   # not f-string
    try:
        result = _execute_order(order_id)
        logger.info("Order %s completed: status=%s", order_id, result.status)
    except OrderNotFoundError:
        logger.warning("Order %s not found, skipping", order_id)
        raise
    except Exception:
        logger.exception("Unexpected error processing order %s", order_id)  # includes traceback
        raise
